<script lang="ts">
 import {workspaceMotion} from "./motion";
 import '../materials.css';
 import DevelopmentMasters from './DevelopmentMasters.svelte';
 import {onMount} from 'svelte';
 import JsBarcode from 'jsbarcode';
 import {api,uploadTo,day} from './api';
 import {convertMeasurement} from './materialMeasurements';
 import type {Row} from './types';
 let {companyID=0}:{companyID?:number}=$props();
 let data:Row=$state({samples:[],options:[],suppliers:[],companies:[],fields:[],option_kinds:[]});
 let tab=$state('Fabric library'),search=$state(''),filter:Row=$state({}),selected:Row|null=$state(null),form:Row|null=$state(null),option:Row|null=$state(null),rating:Row|null=$state(null);
 let busy=$state(false),error=$state(''),notice=$state(''),printSample:Row|null=$state(null),copies=$state(1),photoFiles=$state<HTMLInputElement>(null!);
 let optionTarget:{row:Row,key:string,numeric:boolean}|null=$state(null);
 const selectKind=(key:string)=>key==='currency'?'currency':'unit';
 function choices(kind:string,defaults:string[]){return [...new Set([...defaults,...data.options.filter((o:Row)=>o.active&&o.company_id===Number(form?.company_id)&&o.kind===kind).map((o:Row)=>o.label)])]}
 function addChoice(kind:string,row:Row,key:string,numeric=false){error='';optionTarget={row,key,numeric};option={company_id:form!.company_id,kind,label:'',active:true,parent_id:kind==='weave'?form!.profile.category:kind==='sub_item'?form!.profile.weave:''}}
 function resetChildren(key:string){if(key==='category'){form!.profile.weave='';form!.profile.sub_item=''}if(key==='weave')form!.profile.sub_item=''}
 const sections=['Specifications','Measurements','Commercial','Sample details','Additional'];
 const kinds:Record<string,string>={category:'Category',weave:'Weave',sub_item:'Sub-item',composition:'Composition',product:'Product',color:'Colour',swatch_type:'Swatch type',finish_type:'Finish type',season:'Season',trim_type:'Trim type',unit:'Unit',currency:'Currency',weight_unit:'Weight unit',width_unit:'Width unit',development_type:'Development type',fit:'Fit',feature:'Feature'};
 const label=(id:unknown)=>data.options.find((o:Row)=>String(o.id)===String(id))?.label||'—';
 const supplier=(id:unknown)=>data.suppliers.find((s:Row)=>s.id===id);
 const editAllowed=(kind:string)=>kind==='fabric'?data.can_edit_fabric:data.can_edit_trim;
 const measurement=(p:Row,key:string)=>(p.measurements||[]).map((m:Row)=>`${m[key]||0}${m[key+'_max']?'–'+m[key+'_max']:''} ${m[key+'_unit']}`).join(' · ')||'—';
 let filtered=$derived(data.samples.filter((s:Row)=>{
  if(companyID&&s.company_id!==companyID)return false;if(s.kind!==(tab==='Trim library'?'trim':'fabric'))return false;
  const p=s.profile;const all=[s.code,p.article,supplier(s.supplier_setup_id)?.legal_name,p.construction,p.counter_ref,p.finishing_ref,p.legacy_reference,p.location,...['category','weave','sub_item','composition','color','season','product'].map(k=>label(p[k])),measurement(p,'weight'),measurement(p,'width')].join(' ').toLowerCase();
  return (!search||all.includes(search.toLowerCase()))&&Object.entries(filter).every(([k,v])=>!v||(k==='supplier'?String(s.supplier_setup_id)===String(v):k==='from'?p.received_on>=v:k==='to'?p.received_on<=v:String(p[k])===String(v)));
 }));
 let shownOptions=$derived(data.options.filter((o:Row)=>(!companyID||o.company_id===companyID)&&(!search||(o.label+' '+o.kind).toLowerCase().includes(search.toLowerCase()))));
 async function load(){data=await api('/materials')}
 onMount(()=>{load().catch(e=>error=e.message)});
 async function run(fn:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await fn()}catch(e){error=(e as Error).message}finally{busy=false}}
 function chooseTab(next:string){tab=next;search='';filter={};selected=null}
 async function open(s:Row){await run(async()=>{selected=await api('/materials/'+s.id)})}
 function optionsFor(f:Row,p:Row){return data.options.filter((o:Row)=>o.company_id===Number(form?.company_id||companyID)&&o.kind===f.options&&o.active&&(f.key!=='weave'||String(o.parent_id)===String(p.category))&&(f.key!=='sub_item'||String(o.parent_id)===String(p.weave)))}
 function start(kind:string,s?:Row){error='';if(!s&&!companyID&&data.companies.length>1){error='Select a workspace company before creating a reference.';return}if(s){form=structuredClone($state.snapshot(s));form!.profile.measurements||=[];form!.profile.additional||=[];return}
  form={company_id:companyID||data.companies[0]?.id,supplier_setup_id:'',kind,origin:'India',active:true,profile:{received_on:new Date().toISOString().slice(0,10),price_date:new Date().toISOString().slice(0,10),quantity_unit:'Metre',price_unit:'Metre',currency:'USD',measurements:[],additional:[]}};
 }
 function changeCompany(){if(!form)return;for(const f of data.fields.filter((f:Row)=>f.type==='option'))form.profile[f.key]=''}
 const payload=(row:Row|null,keys:string[])=>Object.fromEntries(keys.map(k=>[k,row?.[k]]));
 async function save(e:SubmitEvent){e.preventDefault();await run(async()=>{const result=await api('/materials'+(form?.id?'/'+form.id:''),payload(form,['company_id','supplier_setup_id','kind','origin','active','version','profile']));form=null;await load();selected=await api('/materials/'+result.id);notice=result.code+' saved.'})}
 function showDialog(node:HTMLDialogElement){node.showModal();return{destroy(){node.close()}}}
 function barcode(node:SVGSVGElement,code:string){JsBarcode(node,code,{format:'CODE128',width:2,height:60,displayValue:true,fontSize:15,margin:12});return{update(code:string){JsBarcode(node,code,{format:'CODE128',width:2,height:60,displayValue:true,fontSize:15,margin:12})}}}
 async function photos(){const files=[...(photoFiles?.files||[])];if(!selected||!files.length)return;await run(async()=>{let uploaded=0;try{for(const f of files){await uploadTo('/materials/'+selected!.id+'/photos',f);uploaded++}}finally{selected=await api('/materials/'+selected!.id);photoFiles.value='';if(uploaded)notice=uploaded+' photo(s) uploaded.'}})}
 function newOption(o?:Row){optionTarget=null;option=o?structuredClone($state.snapshot(o)):{company_id:companyID||data.companies[0]?.id,kind:'category',label:'',parent_id:'',active:true}}
 async function saveOption(e:SubmitEvent){e.preventDefault();await run(async()=>{const result=await api('/material-options'+(option?.id?'/'+option.id:''),payload(option,['company_id','kind','label','parent_id','active','version']));const savedLabel=option!.label.trim();await load();if(optionTarget){optionTarget.row[optionTarget.key]=optionTarget.numeric?result.id:savedLabel;if(optionTarget.numeric)resetChildren(optionTarget.key)}option=null;optionTarget=null;notice='Master list updated.'})}
 async function saveRating(e:SubmitEvent){e.preventDefault();await run(async()=>{await api('/material-suppliers/'+rating!.id+'/rating',{rating:rating!.rating,reason:rating!.rating_reason,version:rating!.rating_version});rating=null;await load();notice='Supplier rating updated.'})}
</script>
<section class="material-workspace" use:workspaceMotion={tab}>
 <div class="panel-header"><div><p class="eyebrow">MASTER DATA</p><h2>Materials & sample library</h2><p>One permanent reference. Clear specifications. A traceable history.</p></div>{#if ['Fabric library','Trim library'].includes(tab)&&editAllowed(tab==='Trim library'?'trim':'fabric')}<button class="button primary" disabled={busy} onclick={()=>start(tab==='Trim library'?'trim':'fabric')}>{tab==='Trim library'?'Add trim sample':'ETF/ESF Generate'}</button>{/if}</div>
 <div class="filter-tabs material-tabs">{#each ['Fabric library','Trim library',...(data.can_development?['Development masters']:[]),...(data.can_masters?['Master lists']:[]),...(data.commercial?['Supplier ratings']:[])] as t}<button class:active={tab===t} onclick={()=>chooseTab(t)}>{t}</button>{/each}</div>
 {#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if notice}<p class="company-notice" role="status">{notice}</p>{/if}
 {#if data.truncated}<p class="company-warning">Showing the newest 10,000 samples. Older records remain stored; contact Admin for a full extraction.</p>{/if}
 {#if tab==='Development masters'}<DevelopmentMasters {companyID} materials={data.samples} companies={data.companies}/>{:else if tab==='Master lists'}
 <section class="panel"><div class="panel-header"><div><h3>Editable master lists</h3><p>Category → weave → sub-item. Archive old choices without deleting history.</p></div><button class="button primary" onclick={()=>newOption()}>Add master value</button></div><input aria-label="Search master lists" bind:value={search} placeholder="Search a master value"/><div class="table-wrap"><table><thead><tr><th>List</th><th>Value</th><th>Parent</th><th>Status</th><th></th></tr></thead><tbody>{#each shownOptions as o}<tr><td>{kinds[o.kind]}</td><td>{o.label}</td><td>{label(o.parent_id)}</td><td>{o.active?'Active':'Archived'}</td><td><button class="text-button" onclick={()=>newOption(o)}>Edit</button></td></tr>{:else}<tr><td colspan="5">Create your first category, then add its weaves and sub-items.</td></tr>{/each}</tbody></table></div></section>
 {:else if tab==='Supplier ratings'}
 <section class="panel"><div class="panel-header"><div><h3>Approved supplier directory</h3><p>Finance registers suppliers in Company Setup. MD or Super Admin controls ratings and blocks.</p></div></div><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Country</th><th>Rating</th><th>Reason</th><th></th></tr></thead><tbody>{#each data.suppliers as s}<tr><td>{s.legal_name}</td><td>{s.country}</td><td>{s.rating}</td><td>{s.rating_reason||'—'}</td><td>{#if data.can_rate}<button class="text-button" onclick={()=>rating=structuredClone($state.snapshot(s))}>Update rating</button>{/if}</td></tr>{:else}<tr><td colspan="5">No approved suppliers. Ask Finance to register a supplier and submit it for approval.</td></tr>{/each}</tbody></table></div></section>
 {:else}
 <section class="panel"><div class="material-filters"><label class="wide">Search or scan fabric reference<input bind:value={search} placeholder="Reference, composition, weave, weight…"/></label>{#each ['category','weave','composition','color'] as k}<label>{kinds[k]}<select bind:value={filter[k]}><option value="">All</option>{#each data.options.filter((o:Row)=>o.kind===k&&(!companyID||o.company_id===companyID)) as o}<option value={String(o.id)}>{o.label}</option>{/each}</select></label>{/each}{#if data.commercial}<label>Supplier<select bind:value={filter.supplier}><option value="">All suppliers</option>{#each data.suppliers as s}<option value={String(s.id)}>{s.legal_name}</option>{/each}</select></label><label>Received from<input type="date" bind:value={filter.from}/></label><label>Received to<input type="date" bind:value={filter.to}/></label>{/if}<button class="button secondary" onclick={()=>{filter={};search=''}}>Clear filters</button>{#if filtered.length}<a class="button secondary" href={'/api/materials/export?ids='+filtered.map((s:Row)=>s.id).join(',')}>Export Excel</a>{/if}</div>
 <div class="table-wrap"><table><thead><tr><th>Reference</th><th>Category / weave</th><th>Composition</th><th>Weight</th><th>Width</th><th>Colour</th><th></th></tr></thead><tbody>{#each filtered as s}<tr><td><strong>{s.code}</strong>{#if !s.active}<small>Archived</small>{/if}{#if s.supplier_blocked}<small class="form-error">Unavailable: supplier blocked</small>{/if}</td><td>{label(s.profile.category)}<small>{label(s.profile.weave)}</small></td><td>{label(s.profile.composition)}</td><td>{measurement(s.profile,'weight')}</td><td>{measurement(s.profile,'width')}</td><td>{label(s.profile.color)}</td><td><button class="text-button" onclick={()=>open(s)}>View</button></td></tr>{:else}<tr><td colspan="7">No matching samples. {editAllowed(tab==='Trim library'?'trim':'fabric')?'Add a sample after its supplier is approved.':'Ask the fabric team to register samples.'}</td></tr>{/each}</tbody></table></div></section>
 {/if}
 {#if selected}<section class="panel material-detail"><div class="panel-header"><div><p class="eyebrow">{selected.kind==='fabric'?'FABRIC SAMPLE':'TRIM SAMPLE'}</p><h2>{selected.code}</h2>{#if data.commercial}<p>{supplier(selected.supplier_setup_id)?.legal_name||'Supplier no longer approved'} · Article {selected.profile.article}</p>{/if}</div><div class="row-actions">{#if data.commercial}<button class="button secondary" onclick={()=>{copies=1;printSample=selected}}>Barcode label</button>{/if}{#if editAllowed(selected.kind)}<button class="button primary" onclick={()=>start(selected!.kind,selected!)}>Edit sample</button>{/if}<button class="text-button" onclick={()=>selected=null}>Close</button></div></div>
 <div class="material-specs">{#each (data.commercial?data.fields:data.fields.filter((f:Row)=>['category','weave','composition','color'].includes(f.key))) as f}<div><small>{f.label}</small><strong>{f.type==='option'?label(selected.profile[f.key]):selected.profile[f.key]||'—'}</strong></div>{/each}<div><small>Weight</small><strong>{measurement(selected.profile,'weight')}</strong></div><div><small>Width</small><strong>{measurement(selected.profile,'width')}</strong></div></div>
 {#if data.commercial}
 {#if selected.kind==='trim'}<div class="material-specs">{#each [['trim_type','Trim type'],['size','Size / specification'],['unit','Unit'],['units_per_pack','Units per pack'],['pack_unit','Pack unit']] as [k,l]}<div><small>{l}</small><strong>{selected.profile[k]||'—'}</strong></div>{/each}</div>{/if}
 {#each selected.profile.additional||[] as x}<p><strong>{x.label}</strong>: {x.value}</p>{/each}
 {#if selected.kind==='fabric'}<div class="panel-header"><div><h3>Sample photos</h3><p>Multiple photos · PNG / JPEG · 5 MB each · up to 12 photos.</p></div>{#if data.can_edit_fabric}<label class="button secondary">Upload photos<input class="photo-input" type="file" accept="image/png,image/jpeg" multiple bind:this={photoFiles} disabled={busy} onchange={photos}/></label>{/if}</div><div class="photo-grid">{#each selected.photos||[] as photo}<a href={'/api/material-photos/'+photo.id} target="_blank" rel="noreferrer"><img src={'/api/material-photos/'+photo.id} alt={photo.name}/><small>{photo.name}</small></a>{:else}<p class="muted">No sample photos uploaded.</p>{/each}</div>{/if}
 <h3>Price & change history</h3><p class="muted">Every saved revision keeps its price, quantity basis, author and timestamp.</p><div class="table-wrap"><table><thead><tr><th>Saved at</th><th>By</th><th>Action</th><th>Price</th><th>MOQ / order</th><th>Price date / note</th></tr></thead><tbody>{#each selected.history||[] as h}<tr><td>{new Date(h.created_at).toLocaleString()}</td><td>{h.actor}</td><td>{h.action}</td><td>{h.snapshot.profile?.price||'—'} {h.snapshot.profile?.currency} / {h.snapshot.profile?.price_unit}</td><td>{h.snapshot.profile?.moq_order} {h.snapshot.profile?.quantity_unit}</td><td>{day(h.snapshot.profile?.price_date)}<small>{h.snapshot.profile?.price_note}</small></td></tr>{/each}</tbody></table></div>{/if}
 </section>{/if}
</section>
{#if form}<dialog aria-labelledby="material-form-title" class="material-modal material-dialog" use:showDialog oncancel={()=>form=null}><form onsubmit={save}><header><div><h2 id="material-form-title">{form.id?'Update reference':form.kind==='fabric'?'ETF/ESF Generate':'Register a trim sample'}</h2></div><button type="button" class="text-button" onclick={()=>form=null}>Close</button></header><div class="material-modal-body">
 <div class="company-form-grid"><label>Approved supplier<select bind:value={form.supplier_setup_id} disabled={!!form.id} required><option value="">Choose supplier</option>{#each data.suppliers as s}<option value={s.id} disabled={['Blocked','Delisted'].includes(s.rating)}>{s.legal_name} · {s.rating}</option>{/each}</select></label>{#if !form.id}<label>Reference registered in<select bind:value={form.origin}><option>India</option><option>Dubai</option></select><small>Where the reference is registered, not where the fabric was manufactured.</small></label>{:else}<label class="inline-check"><input type="checkbox" bind:checked={form.active}/>Active sample</label>{/if}</div>{#if !form.id}<div class="reference-note"><strong>{form.profile.old_etf?.trim()?'Existing reference will be used':'Number generated when you save'}</strong><p>{#if form.profile.old_etf?.trim()}{form.profile.old_etf.trim()}{:else}{form.kind==='fabric'?(form.origin==='Dubai'?'ETF':'ESF'):(form.origin==='Dubai'?'ETTR':'ESTR')}-0000001 <span>(format example)</span>{/if}</p><small>An entered Old ETF is kept as the reference; otherwise the system generates a new number. The reference stays fixed when details or prices change. The barcode contains this reference.</small></div>{/if}<p class="material-helper">A missing supplier must be registered by Finance and approved first.</p>
 {#each sections as s}<div class="material-section">
 {#if s==='Measurements'}<p class="muted">Add separate quoted weights and widths. Ranges and measured actual values stay with their units.</p>{#each form.profile.measurements as m,i}{@const converted=convertMeasurement(m)}<fieldset class="detail-card"><legend>Measurement {i+1}</legend><div class="company-form-grid">{#each [['weight','Weight'],['weight_max','Weight upper value (optional)'],['width','Width'],['width_max','Width upper value (optional)'],['actual_weight','Actual weight'],['actual_width','Actual width']] as [k,l]}<label>{l}<input type="number" min="0" step="any" bind:value={m[k]}/></label>{/each}<label>Weight unit<select bind:value={m.weight_unit}>{#each choices('weight_unit',['GSM','g/linear metre','oz/yd²']) as v}<option>{v}</option>{/each}</select>{#if data.can_masters}<button type="button" class="add-choice" onclick={()=>addChoice('weight_unit',m,'weight_unit')}>+ Add new option</button>{/if}</label><label>Width unit<select bind:value={m.width_unit}>{#each choices('width_unit',['cm','inch','metre']) as v}<option>{v}</option>{/each}</select>{#if data.can_masters}<button type="button" class="add-choice" onclick={()=>addChoice('width_unit',m,'width_unit')}>+ Add new option</button>{/if}</label></div><p class="calculator-result">Calculator: {converted.widthCm===null?'Custom width unit':converted.widthCm.toFixed(2)+' cm'} · {converted.gsm===null?'GSM conversion unavailable: check width and units':converted.gsm.toFixed(2)+' GSM'} · {converted.gramsPerMetre===null?'—':converted.gramsPerMetre.toFixed(2)+' g/linear metre'}<small>Based on the first weight and full width. Actual values do not overwrite quoted specifications. Custom units are stored as entered; automatic conversion uses standard units only.</small></p><button type="button" class="text-button danger" onclick={()=>form!.profile.measurements.splice(i,1)}>Remove measurement</button></fieldset>{/each}<button type="button" class="button secondary" onclick={()=>form!.profile.measurements.push({weight:0,width:0,weight_unit:'GSM',width_unit:'inch'})}>Add weight / width</button>
 {:else if s==='Additional'}<p class="muted">Record extra specifications without changing existing master fields.</p>{#each form.profile.additional as x,i}<div class="company-form-grid detail-card"><label>Field name<input bind:value={x.label} maxlength="100" required/></label><label>Value<input bind:value={x.value} maxlength="2000"/></label><button class="text-button danger" type="button" onclick={()=>form!.profile.additional.splice(i,1)}>Remove field</button></div>{/each}<button class="button secondary" type="button" onclick={()=>form!.profile.additional.push({label:'',value:''})}>Add detail</button>
 {:else}<div class="company-form-grid">{#each data.fields.filter((f:Row)=>f.section===s&&(form!.kind==='fabric'||f.key!=='old_etf')) as f}<label class:wide={f.type==='textarea'}>{f.label}{#if f.required} <span class="material-required" aria-label="required">*</span>{/if}{#if f.type==='option'}<select bind:value={form.profile[f.key]} onchange={()=>resetChildren(f.key)}><option value="">Select…</option>{#each optionsFor(f,form.profile) as o}<option value={o.id}>{o.label}</option>{/each}</select>{#if data.can_masters}<button type="button" class="add-choice" disabled={busy||(f.key==='weave'&&!form.profile.category)||(f.key==='sub_item'&&!form.profile.weave)} onclick={()=>addChoice(f.options,form!.profile,f.key,true)}>+ Add new option</button>{/if}{:else if f.type==='select'}<select bind:value={form.profile[f.key]}><option value="">Select…</option>{#each choices(selectKind(f.key),f.options) as v}<option>{v}</option>{/each}</select>{#if data.can_masters}<button type="button" class="add-choice" disabled={busy} onclick={()=>addChoice(selectKind(f.key),form!.profile,f.key)}>+ Add new option</button>{/if}{:else if f.type==='textarea'}<textarea bind:value={form.profile[f.key]} rows="3" maxlength="2000"></textarea>{:else}<input type={f.type} min={f.type==='number'?0:undefined} step={f.type==='number'?'any':undefined} bind:value={form.profile[f.key]} readonly={f.key==='old_etf'&&!!form.id} maxlength={f.key==='old_etf'?80:undefined}/>{#if f.key==='old_etf'}<small>Enter the complete existing reference to use it as this record’s permanent ETF/ESF number. Leave blank to generate a new number.</small>{/if}{/if}</label>{/each}</div>{#if s==='Specifications'&&form.kind==='trim'}<h3>Trim specifications & units</h3><div class="company-form-grid">{#each [['trim_type','Trim type'],['size','Size / dimensions'],['unit','Individual unit'],['units_per_pack','Units per pack (e.g. 5000)'],['pack_unit','Pack unit (e.g. cone)']] as [k,l]}<label>{l}<input bind:value={form.profile[k]} maxlength="1000"/></label>{/each}</div>{/if}{/if}
 </div>{/each}
 </div>{#if error}<p class="form-error" role="alert">{error}</p>{/if}<footer><button type="button" class="button secondary" disabled={busy} onclick={()=>form=null}>Cancel</button><button class="button primary" disabled={busy}>{busy?'Saving…':form.id?'Save revision':form.profile.old_etf?.trim()?'Save existing reference':'Generate reference & save'}</button></footer></form></dialog>{/if}
{#if option}<dialog class="material-modal material-compact" use:showDialog oncancel={()=>option=null}><form onsubmit={saveOption}><h2>{option.id?'Edit master value':'Add master value'}</h2><label>Company<select bind:value={option.company_id} disabled={!!option.id||!!optionTarget}>{#each data.companies as c}<option value={c.id}>{c.name}</option>{/each}</select></label><label>Master list<select bind:value={option.kind} disabled={!!option.id||!!optionTarget} onchange={()=>option!.parent_id=''}>{#each data.option_kinds as k}<option value={k}>{kinds[k]}</option>{/each}</select></label>{#if ['weave','sub_item'].includes(option.kind)}<label>Parent {option.kind==='weave'?'category':'weave'}<select bind:value={option.parent_id} required disabled={!!option.id||!!optionTarget}><option value="">Select parent</option>{#each data.options.filter((o:Row)=>o.active&&o.company_id===Number(option!.company_id)&&o.kind===(option!.kind==='weave'?'category':'weave')) as o}<option value={o.id}>{o.label}</option>{/each}</select></label>{/if}<label>Name<input bind:value={option.label} required maxlength="150"/></label><label class="inline-check"><input type="checkbox" bind:checked={option.active} disabled={!!optionTarget}/>Active choice</label>{#if error}<p class="form-error">{error}</p>{/if}<footer><button type="button" class="button secondary" onclick={()=>option=null}>Cancel</button><button class="button primary" disabled={busy}>Save master value</button></footer></form></dialog>{/if}
{#if rating}<dialog class="material-modal material-compact" use:showDialog oncancel={()=>rating=null}><form onsubmit={saveRating}><h2>Supplier rating</h2><p>{rating.legal_name}</p><label>Rating<select bind:value={rating.rating}>{#each ['Not rated','Good','Acceptable','Avoid','Blocked','Delisted'] as v}<option>{v}</option>{/each}</select></label><label>Reason<textarea bind:value={rating.rating_reason} maxlength="2000" required={['Avoid','Blocked','Delisted'].includes(rating.rating)}></textarea></label><p>Blocking preserves existing samples and history, but prevents new selections and changes.</p>{#if error}<p class="form-error">{error}</p>{/if}<footer><button type="button" class="button secondary" onclick={()=>rating=null}>Cancel</button><button class="button primary" disabled={busy}>Save rating</button></footer></form></dialog>{/if}
{#if printSample}<dialog class="material-modal material-print" use:showDialog oncancel={()=>printSample=null}><div class="no-print"><h2>Barcode labels</h2><label>Number of copies<input type="number" min="1" max="50" bind:value={copies}/></label><p>The barcode contains only the permanent reference.</p><button class="button primary" onclick={()=>window.print()}>Print labels</button><button class="button secondary" onclick={()=>printSample=null}>Close</button></div><div class="label-sheet">{#each Array.from({length:Math.min(50,Math.max(1,Number(copies)||1))}) as _}<article class="sample-label"><strong>EURO SUITS · {printSample.kind==='fabric'?'FABRIC':'TRIM'}</strong><svg role="img" aria-label={'Barcode '+printSample.code} use:barcode={printSample.code}></svg><div>{label(printSample.profile.composition)}</div><div>{measurement(printSample.profile,'weight')} · {measurement(printSample.profile,'width')}</div><small>{label(printSample.profile.color)} · Location {printSample.profile.location||'—'}</small></article>{/each}</div></dialog>{/if}
<style>
.material-workspace{display:grid;gap:20px}.material-tabs{flex-wrap:wrap}.material-filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;padding:20px}.wide{grid-column:1/-1}.material-detail{padding:24px}.material-specs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;padding:22px 0}.material-specs strong,.material-specs small{display:block;overflow-wrap:anywhere}.material-specs strong{font-size:14px}.material-specs small{color:var(--muted);margin-bottom:5px}.photo-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin:20px 0}.photo-grid img{width:100%;height:160px;object-fit:cover;border-radius:10px}.photo-grid small{overflow-wrap:anywhere}.photo-input{max-width:210px}.material-dialog{width:min(1000px,94vw);max-width:1000px}.material-section{padding:20px 0}.calculator-result{background:#eef6f3;padding:14px;border-radius:8px}.calculator-result small{display:block}.material-print{width:min(900px,94vw);max-width:900px}.label-sheet{display:flex;flex-wrap:wrap;gap:8mm;padding:15px}.sample-label{border:1px dashed #bdc8c7;width:85mm;padding:5mm;text-align:center;break-inside:avoid;color:#000;background:#fff}.sample-label svg{width:100%;height:auto}.sample-label small{font-size:11px}table small{display:block}@media(max-width:800px){.material-filters,.material-specs,.photo-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media print{:global(body:has(.material-print)>*){visibility:hidden}.material-print,.material-print *{visibility:visible}.material-print{position:absolute;inset:0;max-height:none;height:auto;width:100%;max-width:none;border:0;overflow:visible}.no-print{display:none}.sample-label{border:none}.label-sheet{padding:0}}
</style>
